// reproduce-leak.js
const React = require('react');
const ReactDOMServer = require('react-dom/server');
const { ConfigProvider, Input } = require('@alifd/next');
// 根据打包产物路径加载底层模块，拿到内部缓存 Map。下面路径可能需按实际打包结构调整。
const ConfigProviderModule = require('@alifd/next/lib/config-provider');
const cache = ConfigProviderModule._contextCache || ConfigProviderModule.cache;

// 定义一个简单组件，每次通过 SSR 渲染它，触发 ConfigProvider 的 mount，但在 SSR 下不会走 componentWillUnmount
function renderOnce(idx) {
  const App = () => (
    <ConfigProvider prefix={`leak-${idx}-`} locale={{ Demo: { msg: `#${idx}` }}}>
      <div>Render #{idx}</div>
      <Input placeholder="test" />
    </ConfigProvider>
  );

  // 调用 renderToString 或 renderToStaticMarkup
  const html = ReactDOMServer.renderToString(React.createElement(App));
  return html;
}

async function testLeak(iterations) {
  console.log('Start leak test:');
  for (let i = 1; i <= iterations; i++) {
    renderOnce(i);
    // 打印当前缓存大小
    console.log(`After render #${i}, cache size =`, cache.size);
    // 可在此处手动用 global.gc() 强制 GC（需用 --expose-gc 启动）
    // if (global.gc) global.gc();
  }
  console.log('Final cache size:', cache.size);
}

// 执行 100 次 SSR 渲染，观察 cache.size 是否持续上升
const ITERATIONS = parseInt(process.argv[2], 10) || 100;
testLeak(ITERATIONS);
